SELECT DATE_FORMAT(ss.sale_date, 'yyyy-MM') AS sale_month, ss.product_id, AVG(i.quantity) AS avg_quantity, COUNT(i.quantity) AS quantity_count FROM inventory i INNER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id GROUP BY DATE_FORMAT(ss.sale_date, 'yyyy-MM'), ss.product_id
